def largest_submatrix_ones(matrix: list) -> int:
    """
    Return the area of the largest all-1 rectangular submatrix.
    """
    if not matrix or not matrix[0]:
        return 0
    rows, cols = (len(matrix), len(matrix[0]))
    heights = [0] * cols
    max_area = 0
    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 1:
                heights[c] += 1
            else:
                heights[c] = 0
        stack = []
        for i in range(cols + 1):
            cur_height = heights[i] if i < cols else 0
            while stack and cur_height < heights[stack[-1]]:
                h = heights[stack.pop()]
                width = i if not stack else i - stack[-1] - 1
                max_area = max(max_area, h * width)
            stack.append(i)
    return max_area

