def serialize_tree(values: list) -> str:
    """
    Serialize a binary tree represented in level order using None.
    Return a comma-separated preorder representation using '#' for missing children.
    """

    def helper(idx: int) -> list[str]:
        if idx >= len(values) or values[idx] is None:
            return ['#']
        left = helper(2 * idx + 1)
        right = helper(2 * idx + 2)
        return [str(values[idx])] + left + right
    return ','.join(helper(0))

