def serialize_tree(values: list) -> str:
    if not values:
        return '#'

    class TreeNode:
        __slots__ = ('val', 'left', 'right')

        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None
    if values[0] is None:
        return '#'
    root = TreeNode(values[0])
    from collections import deque
    q = deque([root])
    i = 1
    n = len(values)
    while q and i < n:
        node = q.popleft()
        if i < n:
            val = values[i]
            i += 1
            if val is not None:
                left_node = TreeNode(val)
                node.left = left_node
                q.append(left_node)
        if i < n:
            val = values[i]
            i += 1
            if val is not None:
                right_node = TreeNode(val)
                node.right = right_node
                q.append(right_node)
    res = []

    def dfs(node):
        if not node:
            res.append('#')
            return
        res.append(str(node.val))
        dfs(node.left)
        dfs(node.right)
    dfs(root)
    return ','.join(res)

