    comma-separated preorder representation using '#' for missing children.
    """
    if not values:
        return ''
    result = []
    stack = [0]
    n = len(values)
    while stack:
        i = stack.pop()
        if i >= n or values[i] is None:
            result.append('#')
        else:
            result.append(str(values[i]))
            stack.append(2 * i + 2)
            stack.append(2 * i + 1)
    return ','.join(result)

