    candidates.sort()
    res = []

    def backtrack(start: int, path: list, current_sum: int):
        if current_sum == target:
            res.append(path[:])
            return
        if current_sum > target:
            return
        for i in range(start, len(candidates)):
            nxt = current_sum + candidates[i]
            if nxt > target:
                break
            path.append(candidates[i])
            backtrack(i, path, nxt)
            path.pop()
    backtrack(0, [], 0)
    res.sort()
    return res

