def partition_equal_subset(nums: list) -> bool:
    """
    Return True if nums can be partitioned into two subsets with equal sum.
    Each element is used at most once.
    """
    total = sum(nums)
    if total % 2 != 0:
        return False
    target = total // 2
    reachable = {0}
    for num in nums:
        new_reachable = set()
        for s in reachable:
            ns = s + num
            if ns == target:
                return True
            if ns < target:
                new_reachable.add(ns)
        reachable.update(new_reachable)
    return target in reachable

