def jump_game_min_jumps(nums: list) -> int:
    """
    Return the minimum number of jumps needed to reach the last index, or -1
    if unreachable.
    """
    n = len(nums)
    if n <= 1:
        return 0
    if nums[0] == 0:
        return -1
    jumps = 0
    current_end = 0
    farthest = 0
    for i in range(n - 1):
        farthest = max(farthest, i + nums[i])
        if i == current_end:
            jumps += 1
            current_end = farthest
            if current_end >= n - 1:
                break
        if i > farthest:
            return -1
    return jumps if current_end >= n - 1 else -1

