def minimum_window_substring(s: str, t: str) -> str:
    """
    Return the shortest substring of s containing every character of t with
    multiplicity. If several windows have the same minimum length, return the
    leftmost. Return "" if impossible.
    """
    if not t or not s:
        return ''
    from collections import Counter
    t_counts = Counter(t)
    required = len(t_counts)
    l = 0
    formed = 0
    window_counts = {}
    ans = (float('inf'), None, None)
    for r, char in enumerate(s):
        window_counts[char] = window_counts.get(char, 0) + 1
        if char in t_counts and window_counts[char] == t_counts[char]:
            formed += 1
        while l <= r and formed == required:
            char_left = s[l]
            if r - l + 1 < ans[0]:
                ans = (r - l + 1, l, r)
            window_counts[char_left] -= 1
            if char_left in t_counts and window_counts[char_left] < t_counts[char_left]:
                formed -= 1
            l += 1
    if ans[0] == float('inf'):
        return ''
    return s[ans[1]:ans[2] + 1]

