def longest_palindromic_substring(s: str) -> str:
    """
    Return the longest palindromic substring. If multiple longest substrings
    exist, return the leftmost one.
    """
    n = len(s)
    if n == 0:
        return ''
    start = 0
    max_len = 1

    def expand(left: int, right: int) -> (int, int):
        """Expand around center and return (pal_start, pal_len)."""
        while left >= 0 and right < n and (s[left] == s[right]):
            left -= 1
            right += 1
        pal_start = left + 1
        pal_len = right - left - 1
        return (pal_start, pal_len)
    for i in range(n):
        pal_start1, pal_len1 = expand(i, i)
        pal_start2, pal_len2 = expand(i, i + 1)
        if pal_len1 > max_len:
            start, max_len = (pal_start1, pal_len1)
        if pal_len2 > max_len:
            start, max_len = (pal_start2, pal_len2)
    return s[start:start + max_len]

