def count_palindromic_substrings(s: str) -> int:
    """
    Return the number of contiguous substrings that are palindromes. Count
    equal-value substrings at different positions separately.
    """
    if not s:
        return 0
    T = '#'.join('^{}$'.format(s))
    n = len(T)
    P = [0] * n
    center = right = 0
    for i in range(1, n - 1):
        mirror = 2 * center - i
        if i < right:
            P[i] = min(right - i, P[mirror])
        while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
            P[i] += 1
        if i + P[i] > right:
            center = i
            right = i + P[i]
    return sum((p // 2 for p in P))

