def house_robber_circular(nums: list) -> int:
    """
    Houses are arranged in a circle. Return the maximum sum of non-adjacent
    house values, where the first and last houses are adjacent.
    """
    if not nums:
        return 0
    n = len(nums)
    if n == 1:
        return nums[0]
    if n == 2:
        return max(nums[0], nums[1])

    def rob_linear(arr: list) -> int:
        prev2, prev1 = (0, 0)
        for val in arr:
            cur = max(prev1, prev2 + val)
            prev2, prev1 = (prev1, cur)
        return prev1
    max_exclude_first = rob_linear(nums[1:])
    max_exclude_last = rob_linear(nums[:-1])
    return max(max_exclude_first, max_exclude_last)

